    "description": "新华社加沙11月27日电（记者徐泽宇）巴勒斯坦伊斯兰抵抗运动（哈马斯）政治局成员巴塞姆·纳伊姆27日表示，哈马斯政治局主席哈利勒·哈亚最小的儿子伊兹丁·哈亚在以军当天的袭击中幸存。 当地消息人士告诉新华社记者，以色列无人机27日凌晨袭击了加沙城西部的一所住宅，伊兹丁·哈亚的妻子在袭击中受重伤。 纳伊姆将袭击称作“国家恐怖主义”，并表示，如果以色列继续不受惩罚地发动袭击，安全与稳定就不可能实现。 哈马斯27日发表声明谴责此次袭击，并指责以…",
