    "content": "新华社科伦坡11月27日电（记者车宏亮）由中国中央广播电视总台制作的专题片《习近平的文化情缘》启播活动27日在斯里兰卡科伦坡举行。即日起，《习近平的文化情缘》（英语版、僧伽罗语版、泰米尔语版）在斯里兰卡国家电视台等主流媒体播出。 《习近平的文化情缘》讲述习近平主席高度重视、亲自擘画推动文物保护利用和文化遗产保护传承的故事，展现习近平主席的深厚文化情怀和对赓续中华文脉、坚定文化自信的深邃思考。 斯里兰卡总理阿马拉苏里亚表示，《习近平的文化情缘》有助于斯里兰卡人民深入了解习近平主席关于文化与文明的主张，为各国如何在坚守…"
