    "content": "针对近日网络流传的“通城县博物馆疑存赝品、展品断代有误”一事，11月26日，央广网记者实地探访了位于湖北省咸宁市通城县银山文化艺术中心北侧的该博物馆。馆长李剑回应称，馆方已在第一时间自查，对存在争议的展品先行下架，承认部分展签存在描述瑕疵并已整改，但对“赝品”指控持保留意见，认为涉事器物属民俗“花钱”而非流通货币，不存在“以假充真”的主观故意，最终结论待省级专家核查后作出。 通城县博物馆（央广网记者赵玲 摄） 争议焦点：“花钱”性质如何界定 此前有网友发帖，指该博物馆陈列的“周元通宝”“洪武通宝”等钱币为“现代仿制…"
