    "content": "台湾九合一选举投票前夕，民进党台北市长候选人沈伯洋星期五（11月27日）晚举行线上“市民之夜”，YouTube直播观看人数突破50万。沈伯洋称，台北已停滞很长一段时间，呼吁市民用手中的选票改变台北的命运。 沈伯洋说，他向往20年后的台北是一个人人都能快乐生活的地方，但这需要有人率先制定计划、绘制蓝图。他认为自己有能力、有愿景、有执行力，也有勇气，非常适合参选台北市长。 沈伯洋也引用诗人泰戈尔的话，称没有任何一个愿望是微不足道的，当市民心中的盼望汇聚在一起，化为选票，就能照亮台北。 他说，台北已经停滞很长一段时间，许…"
