    "content": "新华社阿克拉11月27日电（记者高剑飞）弗里敦消息：当地时间26日，第27批中国援塞拉利昂医疗队派出8名队员前往塞拉利昂首都弗里敦人口密集的克鲁湾社区，开展“百队千村行”义诊活动，累计接诊约200人次。 克鲁湾是弗里敦人口最为稠密的社区之一，长期面临居住拥挤、基础医疗资源匮乏等挑战，当地居民日常就医存在诸多困难。医疗队精准对接社区需求，为受各类常见疾病困扰的居民提供了免费医疗问诊、治疗和药品发放服务。同时，医疗队员还开展健康宣教，帮助居民提升自我健康管理意识与防病能力。 活动现场气氛热烈，前来就诊的居民络绎不绝。克…"
