    "description": "新华社北京11月27日电 记者27日获悉，国家网信办、中央编办、工业和信息化部等十一部门近日联合公布《分布式数字身份互通互认应用规定》。规定旨在促进分布式数字身份创新发展与互通互认应用，建立健全分布式数字身份公共服务体系，支撑国家区块链网络基础共性服务能力建设，将于2027年3月1日起施行。 规定明确，分布式数字身份是指基于区块链等分布式技术，支持用户自主管理身份信息的新型数字身份，由标识符、密钥、可验证凭证和可验证声明构成，可以用于数…",
    "content": "新华社北京11月27日电 记者27日获悉，国家网信办、中央编办、工业和信息化部等十一部门近日联合公布《分布式数字身份互通互认应用规定》。规定旨在促进分布式数字身份创新发展与互通互认应用，建立健全分布式数字身份公共服务体系，支撑国家区块链网络基础共性服务能力建设，将于2027年3月1日起施行。 规定明确，分布式数字身份是指基于区块链等分布式技术，支持用户自主管理身份信息的新型数字身份，由标识符、密钥、可验证凭证和可验证声明构成，可以用于数字账户管理、登录认证、数据授权等场景，旨在解决跨地域、跨行业、跨平台身份互通互认…"
