    "content": "近日，复旦大学附属肿瘤医院胃外科主任医师徐大志收到一封跨越七年的患者感谢信。七年前，患者因贲门癌接受根治手术，得益于徐大志团队推行的舒适化快速康复手术理念，患者术后告别了常规胃管。如今，患者饮食正常、生活完全自理，已平稳度过术后第七个年头。 时间回到2019年，患者确诊贲门中低分化鳞状细胞癌，病情复杂凶险，影像提示肿瘤侵犯胰腺可能性极大，甚至不排除胰腺肿瘤交叉侵犯胃部，属于临床十分少见、处理难度极高的疑难重症。患者辗转多家医院问诊后，得到的结论大多一致：病情晚期、手术风险极高、创伤大、预后不确定，医生普遍建议保守治…"
