    "content": "在近期塞尔维亚议会选举中获胜的选举团体“学生名单-学生获胜”27日在贝尔格莱德举行的记者会上宣布，推举贝尔格莱德大学化学教授拉多米尔·萨伊契奇参加定于12月27日举行的总统选举。 萨伊契奇现年65岁，是塞尔维亚科学与艺术院院士，在10月25日举行的塞议会选举中当选议员。“学生名单-学生获胜”在此次选举中赢得国民议会250个席位中的140席。 塞尔维亚国民议会议长阿莱克桑达尔·丘皮奇11月26日签署决定，定于12月27日提前举行总统选举。9月27日，塞尔维亚时任总统武契奇辞职。"
