    "link": "https://www.chinanews.com.cn/cj/2026/11-27/10739068.shtml",
    "pub_date": "2026-11-27 21:55:25",
    "author": "",
    "description": "中新网深圳11月27日电(记者 索有为)“广货行天下”冬季行动启动仪式27日在深圳华强北街区举行。活动现场，“科技产品年货大礼包”和“农特产品年货大礼包”同步推出，一边链接华强北的AI硬件创新链，一边汇聚岭南田间地头的年味好物，为不同人群、不同场景提供更精准的年货选择。",
