    "description": "长期困扰外卖骑手、司机、快递员的算法约束、不合理扣罚，迎来实质性调整。 截至11月10日，网络货运、网约车、网约配送、快递4个行业18家重点平台企业已全部完成劳动规则和算法协商并签订协议，覆盖新就业形态劳动者超过2500万人。 编导：徐宁 新华社音视频部制作",
    "content": "长期困扰外卖骑手、司机、快递员的算法约束、不合理扣罚，迎来实质性调整。 截至11月10日，网络货运、网约车、网约配送、快递4个行业18家重点平台企业已全部完成劳动规则和算法协商并签订协议，覆盖新就业形态劳动者超过2500万人。 编导：徐宁 新华社音视频部制作"
