    "description": "新华社北京11月27日电 国家互联网信息办公室11月27日发布的《全民数字素养与技能调查报告（2026年）》显示，2026年我国成年公民中具备初级及以上数字素养与技能的占比为64.69%，高级水平占比为17.65%，较2024年分别增长4.08个和1.39个百分点，全民数字素养与技能发展总体呈良好态势。 报告从总体情况、地区情况、群体情况等方面，系统分析了我国公民数字素养与技能发展水平及变化趋势。从区域维度看，我国公民数字素养与技能发展…",
    "content": "新华社北京11月27日电 国家互联网信息办公室11月27日发布的《全民数字素养与技能调查报告（2026年）》显示，2026年我国成年公民中具备初级及以上数字素养与技能的占比为64.69%，高级水平占比为17.65%，较2024年分别增长4.08个和1.39个百分点，全民数字素养与技能发展总体呈良好态势。 报告从总体情况、地区情况、群体情况等方面，系统分析了我国公民数字素养与技能发展水平及变化趋势。从区域维度看，我国公民数字素养与技能发展水平呈现东部地区持续领跑、中部地区稳步跟进、西部地区加速追赶的发展态势。从城乡、…"
