    "description": "人民币存贷款利率迎来统一的管理制度。 11月27日，中国人民银行发布《人民币存贷款利率管理规定》（下称《规定》），自2027年3月21日起施行。原《人民币利率管理规定》同时废止。 随着利率市场化改革不断推进，当前各项存贷款利率已由金融机构按市场化原则自主确定，市场利率定价自律机制的作用也日益重要，一些规定和表述已不再适应利率管理的需要。同时，个人存款、单位存款、通知存款、短期贷款、中长期贷款等类别存贷款的计结息规则，散落在《关于执行〈储…",
    "content": "人民币存贷款利率迎来统一的管理制度。 11月27日，中国人民银行发布《人民币存贷款利率管理规定》（下称《规定》），自2027年3月21日起施行。原《人民币利率管理规定》同时废止。 随着利率市场化改革不断推进，当前各项存贷款利率已由金融机构按市场化原则自主确定，市场利率定价自律机制的作用也日益重要，一些规定和表述已不再适应利率管理的需要。同时，个人存款、单位存款、通知存款、短期贷款、中长期贷款等类别存贷款的计结息规则，散落在《关于执行〈储蓄管理条例〉的若干规定》《人民币单位存款管理规定》《通知存款管理规定》等多份文件…"
