    "author": "",
    "description": "新华社北京11月27日电（记者魏梦佳）近日，随着纪录片《中华古树》之《北京大学古树群》的热播，“北大古树”火出了圈。七叶树、圆柏、银杏、流苏……一株株古树走进视野，翻开了一部比校史更悠远的绿色典籍。 记者从北大获悉，该校校园内现有在册古树538株，总量居全国高校首位。这些古树大多是国槐、圆柏、侧柏、油松、白皮松、银杏等。其中，树龄超过300年的一级古树28株，100年至300年的二级古树510株。 扎根于北京大学未名湖南岸的一株桧柏，是…",
    "content": "新华社北京11月27日电（记者魏梦佳）近日，随着纪录片《中华古树》之《北京大学古树群》的热播，“北大古树”火出了圈。七叶树、圆柏、银杏、流苏……一株株古树走进视野，翻开了一部比校史更悠远的绿色典籍。 记者从北大获悉，该校校园内现有在册古树538株，总量居全国高校首位。这些古树大多是国槐、圆柏、侧柏、油松、白皮松、银杏等。其中，树龄超过300年的一级古树28株，100年至300年的二级古树510株。 扎根于北京大学未名湖南岸的一株桧柏，是北京市海淀区登记在册的第一棵古树。它树龄约320年，树高9.5米，胸围210厘米…"
