    "content": "新华社天津11月27日电（记者马博文）27日，天津市十八届人大常委会第二十九次会议表决通过《天津市文商旅融合发展促进条例》。 “制定条例是落实天津城市功能定位、巩固发展成果的迫切需要，为以法治方式促进文商旅融合发展提供了重要支撑。”天津市人大教科文卫委副主任委员李旭炎介绍。 近年来，天津持续建设特色鲜明的文化旅游目的地、国际消费中心城市，文旅品牌影响力不断提升、消费场景日益丰富、特色资源活化利用成效明显。2025年，天津接待游客2.72亿人次，旅游花费3200亿元，文旅增加值占GDP比重升至3.5%。 “文商旅融合…"
