    "content": "这一次，喀什古城迎来了遥远的客人。 喀什，中国最西端的一座城市，再往西，就是帕米尔高原。古丝绸之路的南北两道走到这里合成一条，驼队在这里卸货、换水、修整，然后翻山越岭。喀什就是这样生长起来的。 不到喀什，就不能说是来了新疆；不来喀什古城，就不能说是来了喀什。 喀什古城是世界上仍在使用的最大规模的生土建筑群，它不仅仅是一个景区，而是一座会“呼吸”的古城，当地的居民世世代代在这里繁衍生息，来到喀什古城，你体会到的是最原汁原味的新疆风情。 喀什人待客有句老话：尊贵的客人，要请到家里。古城的民宿业搞得是热气腾腾。“古丽的家…"
