    "content": "新华社南宁11月27日电（记者梁舜、田子骏）11月27日，广西海岛低空物流支线完成首飞，这标志着“北海合浦—涠洲岛”低空航线正式启航，填补了广西海岛物流运输低空场景的空白。 当日14时08分，一架福昆航空E80A中型复合翼无人机搭载报刊、民用生活物资及特快函件，从中国邮政速递物流股份有限公司北海市合浦寄递物流共配中心起飞，跨越北部湾海域，于14时51分平稳降落在广西旅发沿海投资发展有限公司北海涠洲岛直升机场。经测算，此航线距离约78公里，空中飞行43分钟，较约2小时的传统轮渡运输缩短1小时以上。 长期以来，涠洲岛进…"
