    "content": "中国海警通报，驱离了日本进入钓鱼岛（日称尖阁诸岛）的渔船。日本方面则指，中国公务船连续两天进入尖阁周边领海。 据“中国海警”微信公众号消息，中国海警局新闻发言人姜略星期五（11月27日）表示，本周四（11月26日），日本“第三奖弥丸”号渔船进入钓鱼岛海域，中国海警舰艇“对其采取必要管控措施并警告驱离”。 姜略称，“钓鱼岛及其附属岛屿是中国固有领土，我们敦促日方立即停止在该海域的一切侵权挑衅行径。中国海警将持续在钓鱼岛及其附属岛屿领海内开展维权执法，维护国家领土主权和海洋权益”。 据日本共同社报道，日本第11管区海上…"
