    "content": "上周有个大二的学生发消息给我，说小组作业要做课堂展示，老师给的课件是直接截图发在群里的，一共十一张，有的是从 PPT 画面截的，有的是拿手机拍屏幕拍的，边上还带着桌角和反光。她想把这些图弄成一版自己能改的 PPT，主要是把老师写的旧年份、旧数据换掉，再补上自己小组的内容。 我的做法是先按页拆开，把拍糊的斜边和反光裁掉，再让工具把每页认成文本框和形状。十一页弄完大概二十来分钟，比我预想的快，因为课件排版还算规矩，标题一行、正文几行，认出来的位置基本对得上。学生自己要改的那几处数据，改起来也就是点进去替换。 有两页必须…"
