    "content": "新华社北京11月27日电 题：国常会新部署释放明确稳市信号 新华社记者刘慧、刘羽佳 11月27日举行的国务院常务会议研究了持续深化资本市场投融资综合改革工作，释放五大鲜明稳市信号。截至当日收盘，A股超5000只个股飘红，成交明显放量。 信号一：明确“资本市场事关经济发展大局”。 资本市场一头连着企业融资、产业升级，另一头连着居民资产、财产性收入。 会议指出，资本市场事关经济发展大局。在招商证券研究发展中心负责人谢亚轩看来，会议把资本市场放在经济发展大局中谋划，定位清晰。企业直接融资渠道是否畅通，科技创新、先进制造能…"
